#include <vector>
#include <stack>
#include <algorithm>
using namespace std;

class Solution {
public:
    /**
     * 方法一：單調棧
     * 時間複雜度: O(n)
     * 空間複雜度: O(n)
     */
    int largestRectangleArea(vector<int>& heights) {
        stack<int> st;
        int maxArea = 0;
        int n = heights.size();

        for (int i = 0; i < n; i++) {
            while (!st.empty() && heights[st.top()] > heights[i]) {
                int h = heights[st.top()];
                st.pop();
                int w = st.empty() ? i : i - st.top() - 1;
                maxArea = max(maxArea, h * w);
            }
            st.push(i);
        }

        // 處理剩餘元素
        while (!st.empty()) {
            int h = heights[st.top()];
            st.pop();
            int w = st.empty() ? n : n - st.top() - 1;
            maxArea = max(maxArea, h * w);
        }

        return maxArea;
    }

    /**
     * 方法二：哨兵優化
     */
    int largestRectangleArea_sentinel(vector<int>& heights) {
        heights.insert(heights.begin(), 0);
        heights.push_back(0);

        stack<int> st;
        st.push(0);
        int maxArea = 0;

        for (int i = 1; i < heights.size(); i++) {
            while (heights[st.top()] > heights[i]) {
                int h = heights[st.top()];
                st.pop();
                int w = i - st.top() - 1;
                maxArea = max(maxArea, h * w);
            }
            st.push(i);
        }

        return maxArea;
    }
};

